Ensure that the utility functions `countBy` and `countByCodes` are robust against non-array inputs by returning an empty object as a safe default. Also, verify that `pathAccessor` is a valid function before invoking it.

```javascript
function countBy(list, field) {
  if (!Array.isArray(list)) {
    return {};
  }
  const buckets = {};
  for (const item of list) {
    const key = typeof field === 'function' ? field(item) : item?.[field];
    const label = key === undefined ? 'unknown' : String(key);
    buckets[label] = (buckets[label] || 0) + 1;
  }
  return buckets;
}

function countByCodes(items, pathAccessor) {
  if (!Array.isArray(items)) {
    return {};
  }
  const buckets = {};
  for (const item of items) {
    const list = typeof pathAccessor === 'function' ? pathAccessor(item) : [];
    const listArray = Array.isArray(list) ? list : [];
    if (listArray.length === 0) {
      const label = 'none';
      buckets[label] = (buckets[label] || 0) + 1;
      continue;
    }
    for (const value of listArray) {
      const label = value || 'none';
      buckets[label] = (buckets[label] || 0) + 1;
    }
  }
  return buckets;
}
```

