Add defensive guards to check if `reason` is a valid object before accessing `reason.code`, and ensure `candidate` is also a valid object to prevent potential `TypeErrors`.

```javascript
function mapBlockerReasons(result, candidate) {
  const reasonCodes = Array.isArray(result?.structured_reasons)
    ? result.structured_reasons
        .filter((reason) => reason && typeof reason === 'object')
        .map((reason) => reason.code)
        .filter(Boolean)
    : [];
  const withConstraint = new Set(reasonCodes);
  if (candidate && (candidate.status === 'raw_candidate'
    || candidate.status === 'triangulated_candidate'
    || candidate.status === 'provisional_safe'
    || candidate.status === 'blocked_quarantined'
    || candidate.status === 'rejected')) {
    withConstraint.add(SOURCE_CONSTRAINT_ID);
  }
  if (!result && candidate && candidate.status !== 'accepted' && candidate.status !== 'triangulated_candidate') {
    withConstraint.add(SOURCE_CONSTRAINT_ID);
  }
  return [...withConstraint].sort(compareByteOrder);
}
```

