+  return [...withConstraint].sort(compareByteOrder);
+}
+
+function buildPilotCandidates({
+  boundary,
+  inputs,
+  triResultById,
+}) {
+  const sourceRows = Array.isArray(inputs.rawCandidates?.candidates) ? inputs.rawCandidates.candidates : [];
+  const boundedRows = sourceRows.slice(0, SOURCE_CONSTRAINT_MAX);
+  const normalizedRows = boundedRows
+    .map((candidate) => {
+      const triResult = triResultById.get(candidate.candidate_id) ?? null;
+      const status = ALLOWED_STATUSES.has(candidate.status) ? candidate.status : 'raw_candidate';
+      const blocker_reasons = mapBlockerReasons(triResult, candidate);
+      return {
+        candidate_id: stableCandidateId(candidate.candidate_id),
+        source_candidate_id: candidate.candidate_id,
+        schema_version: 'semantic_kg_bounded_pilot_candidate.v1',
+        subject_code: SUBJECT_CODE,
+        predicate: candidate.predicate,
+        edge_type: candidate.predicate,
+        status,
+        risk_tier: candidate.risk_tier ?? 'medium_risk_question_concept_skill_procedure',
+        source_artifact_refs: [
+          ...artifactMetaArray(candidate?.provenance?.source_artifact_refs),
+          {
+            path: DEFAULT_PATHS.noAuthReceiptIn,
+            json_pointer: '/',
+          },
+          {
+            path: DEFAULT_PATHS.triangulationValidatorIn,
+            json_pointer: '/',
+          },
+          {
+            path: DEFAULT_PATHS.dedupeGateValidatorIn,
+            json_pointer: '/',
+          },
+          {
+            path: DEFAULT_PATHS.goldFixtureValidatorIn,
+            json_pointer: '/',
+          },
+          {
+            path: DEFAULT_PATHS.procedurePilotValidatorIn,
+            json_pointer: '/',
+          },
+        ].filter((entry) => Boolean(entry.path)),
+        subject_ref: candidate.subject_ref,
+        object_ref: candidate.object_ref,
+        scope_ref: candidate.scope_ref,
+        review_routing: mapReviewStateFromTriResult(triResult),
+        blocker_reasons,
+        provenance: {
+          source_artifact_refs: [
+            {
+              path: DEFAULT_PATHS.rawCandidatesIn,
+              json_pointer: `/candidates/${candidate.candidate_id}`,
+            },
+          ],
+          generator: {
+            actor_type: 'system',
+            actor_id: SCRIPT_NAME,
+            run_mode: 'no_auth_local_bounded_pilot',
+            external_model_call_count: 0,
+          },
+          validator: {
+            actor_type: 'system',
+            actor_id: SCRIPT_NAME,
+            result_artifact_ref: DEFAULT_PATHS.validatorOut,
+          },
+          timestamp: inputs.generatedAt,
+        },
+      };
+    })
+    .sort((left, right) => compareByteOrder(left.candidate_id, right.candidate_id));
+
+  const summary = {
+    pilot_candidate_count: normalizedRows.length,
+    bounded_source_count: normalizedRows.length,
+    source_constraint: {
+      code: SOURCE_CONSTRAINT_ID,
+      requested_min: SOURCE_CONSTRAINT_MIN,
+      requested_max: SOURCE_CONSTRAINT_MAX,
+      raw_candidate_source_count: boundedRows.length,
+      note:
+        'no-auth source mode is intentionally limited to available fixture-backed candidates (3) rather than 100-200 calibration target.',
+    },
+    status_counts: countBy(normalizedRows, 'status'),
+    edge_type_counts: countBy(normalizedRows, 'edge_type'),
+    risk_tier_counts: countBy(normalizedRows, 'risk_tier'),
+    blocker_reason_counts: countByCodes(normalizedRows, (item) => item.blocker_reasons),
+    review_routing_counts: countBy(normalizedRows, (item) => item.review_routing?.queue || item.review_routing?.review_state || 'none'),
+    accepted_candidate_count: normalizedRows.filter((row) => row.status === 'accepted').length,
+    external_model_call_count: boundary.external_model_call_count,
+    candidate_statuses_allowed_only: ALLOWED_STATUSES.size,
+    no_accepted_by_default: boundary.no_accepted_by_default,
+    no_frontend_ui: boundary.no_frontend_ui,
+  };
+
+  return { candidates: normalizedRows, summary };
+}
+
+function artifactMetaArray(values) {
+  if (!Array.isArray(values)) {
+    return [];
+  }
+  return values
+    .map((value, index) => {
+      if (!value?.path) {
+        return null;
+      }
+      return {
+        path: value.path,
+        json_pointer: value.json_pointer ?? `/${index}`,
+      };
+    })
+    .filter(Boolean);
+}
+
+function isObject(value) {
+  return value !== null && typeof value === 'object' && !Array.isArray(value);
+}
+
+function addCheck(checks, id, status, details = {}) {
+  checks.push({
+    id,
+    status: status ? 'pass' : 'fail',
+    ...details,
+  });
+}
+
+function buildChecks({ boundary, pilot, sourceContract, inputDiagnostics, allowedStatuses }) {
+  const checks = [];
+  const criticalDiagnostics = inputDiagnostics.filter((diagnostic) => diagnostic.severity === 'critical');
+  const candidateRows = Array.isArray(pilot.candidates) ? pilot.candidates : [];
+  const ids = candidateRows.map((row) => row.candidate_id);
+  const sortedIds = [...ids].sort(compareByteOrder);
+
+  addCheck(checks, 'boundary_no_auth_enforced',
+    boundary.no_auth_mode === true
+      && boundary.external_model_call_count === 0
+      && boundary.no_accepted_by_default === true,
+    { boundary },
+  );
+  addCheck(checks, 'candidate_generation_mode_no_auth',
+    boundary.no_auth_mode === true && boundary.no_frontend_ui === true,
+    { no_auth_mode: boundary.no_auth_mode, no_frontend_ui: boundary.no_frontend_ui },
+  );
+  addCheck(checks, 'candidate_statuses_allowed_only',
+    candidateRows.every((row) => allowedStatuses.has(row.status)),
+    {
+      allowed_statuses: [...allowedStatuses].sort(compareByteOrder),
+      observed_statuses: Object.keys(countBy(candidateRows, 'status')).sort(compareByteOrder),
+    },
+  );
+  addCheck(checks, 'candidate_ids_deterministic',
+    ids.every((value, index) => value === sortedIds[index]),
+    {
+      candidate_count: ids.length,
+      sorted: ids.length > 0 && ids.every((value, index) => value === sortedIds[index]),
+    },
+  );
+  addCheck(checks, 'source_constraint_recorded',
+    boundary.source_limit_policy.raw_candidate_source_count >= 0,
+    {
+      source_constraint_id: boundary.source_limit_policy?.source_constraint_id ?? SOURCE_CONSTRAINT_ID,
+      source_limit_policy: boundary.source_limit_policy,
+    },
+  );
+  addCheck(checks, 'input_artifacts_loaded',
+    criticalDiagnostics.length === 0,
+    { input_diagnostics: inputDiagnostics },
+  );
+  addCheck(checks, 'candidate_summary_reflects_inputs',
+    pilot.summary.bounded_source_count <= sourceContract.raw_candidate_source_artifact_count,
+    {
+      bounded_source_count: pilot.summary.bounded_source_count,
+      raw_candidate_source_artifact_count: sourceContract.raw_candidate_source_artifact_count,
+    },
+  );
+  addCheck(checks, 'validation_boundary_fields_present',
+    boundary.no_frontend_ui === true
+      && boundary.remote_supabase_mutation_performed === false
+      && boundary.production_rag_reindex_performed === false,
+    {
+      no_frontend_ui: boundary.no_frontend_ui,
+      remote_supabase_mutation_performed: boundary.remote_supabase_mutation_performed,
+      production_rag_reindex_performed: boundary.production_rag_reindex_performed,
+    },
+  );
+  addCheck(checks, 'triangulation_validator_passed',
+    sourceContract.triangulation_validation_status === 'pass',
+    {
+      path: sourceContract.triangulation_validator_path,
+      status: sourceContract.triangulation_validation_status,
+    },
+  );
+  addCheck(checks, 'dedupe_gate_validator_passed',
+    sourceContract.dedupe_gate_validation_status === 'pass',
+    {
+      path: sourceContract.dedupe_gate_validator_path,
+      status: sourceContract.dedupe_gate_validation_status,
+    },
+  );
+  addCheck(checks, 'gold_fixtures_validator_passed',
+    sourceContract.gold_fixture_validation_status === 'pass',
+    {
+      path: sourceContract.gold_fixtures_validator_path,
+      status: sourceContract.gold_fixture_validation_status,
+    },
+  );
+  addCheck(checks, 'procedure_pilot_validator_passed',
+    sourceContract.procedure_pilot_validation_status === 'pass',
+    {
+      path: sourceContract.procedure_pilot_validator_path,
+      status: sourceContract.procedure_pilot_validation_status,
+    },
+  );
+  addCheck(checks, 'no_accepted_candidates',
+    pilot.summary.accepted_candidate_count === 0
+      && candidateRows.every((row) => row.status !== 'accepted'),
+    {
+      accepted_candidate_count: pilot.summary.accepted_candidate_count,
+    },
+  );
+  addCheck(checks, 'candidate_generation_no_auth_receipt_valid',
+    sourceContract.candidate_generator_no_auth_receipt_issue === 1318
+      && sourceContract.candidate_generator_no_auth_receipt_sha256 !== null
+      && sourceContract.candidate_generator_no_auth_receipt_sha256.length > 10,
+    {
+      receipt_issue: sourceContract.candidate_generator_no_auth_receipt_issue,
+      receipt_path: sourceContract.candidate_generator_no_auth_receipt_path,
+      receipt_sha256: sourceContract.candidate_generator_no_auth_receipt_sha256,
+    },
+  );
+
+  checks.sort((left, right) => compareByteOrder(left.id, right.id));
+
+  const failedChecks = checks.filter((check) => check.status !== 'pass');
+  return {
+    checks,
+    failedChecks,
+  };
+}
+
+function buildValidatorResult({ generatedAt, pilot, checks, inputDiagnostics, sourceContract }) {
+  const failedChecks = checks.filter((check) => check.status !== 'pass');
+  return {
+    schema_version: 'semantic_kg_bounded_pilot_candidates_validator_result.v1',
+    generated_at: generatedAt,
+    generated_by: SCRIPT_NAME,
+    issue: ISSUE,
+    parent_issue: PARENT_ISSUE,
+    pilot_path: DEFAULT_PATHS.pilotOut,
+    source_contract: sourceContract,
+    checks,
+    summary: {
+      validation_status: failedChecks.length === 0 ? 'pass' : 'fail',
+      failed_check_count: failedChecks.length,
+      pilot_candidate_count: pilot.summary.pilot_candidate_count,
+      bounded_source_count: pilot.summary.bounded_source_count,
+      status_count: Object.keys(pilot.summary.status_counts).length,
+      external_model_call_count: 0,
+      remote_supabase_mutation_performed: false,
+      production_rag_reindex_performed: false,
+      accepted_candidate_count: pilot.summary.accepted_candidate_count,
+      source_constraint_id: SOURCE_CONSTRAINT_ID,
+      blockers: [
+        {
+          id: SOURCE_CONSTRAINT_ID,
+          severity: 'info',
+          reason:
+            'No-auth local-mode has only 3 calibration raw candidates from fixtures, below 100-200 preferred size.',
+          status: 'known_limit',
+        },
+      ],
+    },
+    input_diagnostics: inputDiagnostics,
+  };
+}
+
+function buildReadback({ pilot, sourceContract, validatorResult, boundary }) {
+  const statusCounts = Object.entries(pilot.summary.status_counts || {})
+    .map(([status, count]) => `  - ${status}: ${count}`);
+  const edgeTypeCounts = Object.entries(pilot.summary.edge_type_counts || {})
+    .map(([type, count]) => `  - ${type}: ${count}`);
+  const riskCounts = Object.entries(pilot.summary.risk_tier_counts || {})
+    .map(([risk, count]) => `  - ${risk}: ${count}`);
+  const blockerCounts = Object.entries(pilot.summary.blocker_reason_counts || {})
+    .map(([reason, count]) => `  - ${reason}: ${count}`);
+  const reviewRoutingCounts = Object.entries(pilot.summary.review_routing_counts || {})
+    .map(([route, count]) => `  - ${route}: ${count}`);
+
+  return [
+    '# Semantic KG Bounded Pilot Candidate Readback',
+    '',
+    `Generated at: ${pilot.generated_at}`,
+    `Issue: #${ISSUE}`,
+    `Parent: #${PARENT_ISSUE}`,
+    '',
+    '## Artifacts',
+    `- Pilot candidates: \`${DEFAULT_PATHS.pilotOut}\``,
+    `- Validator result: \`${DEFAULT_PATHS.validatorOut}\``,
+    `- Readback: \`${DEFAULT_PATHS.readbackOut}\``,
+    '',
+    '## No-auth Boundary',
+    `- no_auth_mode: ${boundary.no_auth_mode}`,
+    `- external_model_call_count: ${boundary.external_model_call_count}`,
+    `- remote_supabase_mutation_performed: ${boundary.remote_supabase_mutation_performed}`,
+    `- production_rag_reindex_performed: ${boundary.production_rag_reindex_performed}`,
+    `- no_accepted_by_default: ${boundary.no_accepted_by_default}`,
+    `- accepted_candidate_count: ${boundary.accepted_candidate_count}`,
+    '',
+    '## Calibration Constraint',
+    `- source_constraint: ${SOURCE_CONSTRAINT_ID}`,
+    `- raw candidate source count: ${pilot.summary.source_constraint.raw_candidate_source_count}`,
+    `- requested_min: ${boundary.source_limit_policy.requested_min}`,
+    `- requested_max: ${boundary.source_limit_policy.requested_max}`,
+    `- bounded_source_count: ${pilot.summary.bounded_source_count}`,
+    '',
+    '## Counts',
+    `- Pilot candidates: ${pilot.summary.pilot_candidate_count}`,
+    `- Accepted candidates: ${pilot.summary.accepted_candidate_count}`,
+    `- Blocker reason entries: ${Object.values(pilot.summary.blocker_reason_counts || {}).reduce((sum, value) => sum + value, 0)}`,
+    '',
+    '## Status Counts',
+    ...statusCounts,
+    '',
+    '## Edge Type Counts',
+    ...edgeTypeCounts,
+    '',
+    '## Risk Tier Counts',
+    ...riskCounts,
+    '',
+    '## Blocker Reason Counts',
+    ...blockerCounts,
+    '',
+    '## Review Routing Counts',
+    ...reviewRoutingCounts,
+    '',
+    '## Source Contracts',
+    `- candidate generator no-auth receipt: ${DEFAULT_PATHS.noAuthReceiptIn} (${sourceContract.candidate_generator_no_auth_receipt_sha256})`,
+    `- triangulation validator: ${DEFAULT_PATHS.triangulationValidatorIn} (${sourceContract.triangulation_validation_status})`,
+    `- taxonomy dedupe validator: ${DEFAULT_PATHS.dedupeGateValidatorIn} (${sourceContract.dedupe_gate_validation_status})`,
+    `- gold/adversarial validator: ${DEFAULT_PATHS.goldFixtureValidatorIn} (${sourceContract.gold_fixture_validation_status})`,
+    `- procedure pilot validator: ${DEFAULT_PATHS.procedurePilotValidatorIn} (${sourceContract.procedure_pilot_validation_status})`,
+    '',
+    '## Validation',
+    `- validator status: ${validatorResult.summary.validation_status}`,
+    `- failed checks: ${validatorResult.summary.failed_check_count}`,
+    `- validation commands:`,
+    '  - node scripts/method-map/build-semantic-kg-bounded-pilot-candidates.mjs --write',
+    '  - node --experimental-vm-modules node_modules/jest/bin/jest.js --runInBand scripts/method-map/__tests__/semantic-kg-bounded-pilot-candidates.test.js',
+    '  - npm run workflow:codex-preflight -- --json',
+    '  - npm run lint:changed -- --base efc893ca0c8035c088880c1cc1e9d89146f9664f --json',
+    '',
+    '## Blockers',
+    `- ${SOURCE_CONSTRAINT_ID}`,
+    '  - No-auth calibration is intentionally limited to the 3 fixture-backed candidates available on local source artifacts.',
+    '',
+  ].join('\n');
+}
+
+export function buildSemanticKgBoundedPilotCandidates(options = {}) {
+  const root = typeof options.root === 'string' ? options.root : repoRootFromScript();
+  const paths = {
+    ...DEFAULT_PATHS,
+    ...(options.paths ?? {}),
+  };
+  const generatedAt = options.generatedAt ?? DEFAULT_GENERATED_AT;
+  const inputDiagnostics = [];
+  const inputs = {
+    generatedAt,
+    rawCandidates: readJsonInput(root, paths.rawCandidatesIn, 'semantic_kg_raw_candidate_outputs', inputDiagnostics),
+    noAuthReceipt: readJsonInput(root, paths.noAuthReceiptIn, 'semantic_kg_external_model_not_run_receipt', inputDiagnostics),
+    triangulationValidator: readJsonInput(root, paths.triangulationValidatorIn, 'semantic_kg_triangulation_validator_result', inputDiagnostics),
+    dedupeGateValidator: readJsonInput(root, paths.dedupeGateValidatorIn, 'semantic_kg_taxonomy_canonicalization_dedupe_gate_validator_result', inputDiagnostics),
+    goldFixtureValidator: readJsonInput(root, paths.goldFixtureValidatorIn, 'semantic_kg_gold_adversarial_fixtures_validator_result', inputDiagnostics),
+    procedurePilotValidator: readJsonInput(root, paths.procedurePilotValidatorIn, 'semantic_kg_procedure_worked_solution_pilot_validator_result', inputDiagnostics),
+  };
+
+  const rawCandidateRows = Array.isArray(inputs.rawCandidates?.candidates) ? inputs.rawCandidates.candidates : [];
+  const sourceContract = buildSourceContract(root, inputs);
+  const boundary = buildBoundary(
+    Math.min(rawCandidateRows.length, SOURCE_CONSTRAINT_MAX),
+    rawCandidateRows.length,
+  );
+  const triById = new Map(
+    (Array.isArray(inputs.triangulationValidator?.raw_candidate_results)
+      ? inputs.triangulationValidator.raw_candidate_results
+      : [])
+      .map((result) => [result.assertion_id, result]),
+  );
